FEATURE_MEAN = [0.2378, 13.636288456980099, -0.009194498489131217, 418.88022395299913, 55.64370189919399, 2.9861, 375.6523039017985, 576.6652283240019, 0.4766, 219.88326764740023, 0.46351507951629944, 2.460686118043396]
